head.script:
scwin.CHART_DATA_URL ="/ui/sample/SBChart/CIRCLE/data/CIRCLE.json";
scwin.CHART_CONFIG = {
    global: { color: { theme: "a11y" } },
    extend: {
        pie: {
            fullCircle: false          // ★ 반원(180°) 파이 — 게이지형 달성률 위젯
        }
    }
};
scwin.onpageload = async function () {
    var res = await $c.sbm.executeDynamic({ id: "sbm_sbchart", action: scwin.CHART_DATA_URL, method: "get", mediatype: "application/json", mode: "asynchronous", isProcessMsg: false });
    var data = res.responseJSON;
    $c.ext.drawChartData("pie", data, chartWrap, scwin.CHART_CONFIG);
};
